import * as React from "react";
import { CircleAlert, CircleCheck, Info, X } from "lucide-react";
import { cn } from "@/lib/cn";

type Tone = "default" | "success" | "danger";
export interface ToastItem {
  id: number;
  title: string;
  description?: string;
  tone?: Tone;
  action?: { label: string; onClick: () => void };
  duration?: number;
}

let items: ToastItem[] = [];
let nextId = 1;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());

export function dismissToast(id: number) {
  items = items.filter((t) => t.id !== id);
  emit();
}

/** Show a toast from anywhere: toast("Saved") or toast({ title, description, tone, action }). */
export function toast(input: string | Omit<ToastItem, "id">) {
  const t: ToastItem = typeof input === "string" ? { id: nextId++, title: input } : { id: nextId++, ...input };
  items = [...items, t].slice(-4);
  emit();
  window.setTimeout(() => dismissToast(t.id), t.duration ?? 4000);
  return t.id;
}
toast.success = (title: string, description?: string) => toast({ title, description, tone: "success" });
toast.error = (title: string, description?: string) => toast({ title, description, tone: "danger" });

const icons = { default: Info, success: CircleCheck, danger: CircleAlert };
const iconTone = { default: "text-accent", success: "text-success", danger: "text-danger" };

/** Mount once near the root of your app. */
export function Toaster({ className }: { className?: string }) {
  const list = React.useSyncExternalStore(
    (cb) => {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    () => items,
    () => items,
  );
  return (
    <ol
      aria-live="polite"
      className={cn("pointer-events-none fixed bottom-4 right-4 z-[500] flex w-[min(360px,calc(100vw-2rem))] flex-col gap-2", className)}
    >
      {list.map((t) => {
        const Icon = icons[t.tone ?? "default"];
        return (
          <li
            key={t.id}
            className="vx-toast pointer-events-auto flex items-start gap-3 rounded-card border border-pop-border bg-pop p-3.5 text-sm text-ink shadow-pop vx-glass"
          >
            <Icon className={cn("mt-0.5 size-4 shrink-0", iconTone[t.tone ?? "default"])} />
            <div className="grid flex-1 gap-0.5">
              <p className="font-medium">{t.title}</p>
              {t.description && <p className="text-muted">{t.description}</p>}
            </div>
            {t.action && (
              <button
                onClick={() => {
                  t.action!.onClick();
                  dismissToast(t.id);
                }}
                className="rounded-sm px-1.5 py-0.5 text-sm font-medium text-accent hover:bg-accent-wash focus-visible:outline-2 focus-visible:outline-focus"
              >
                {t.action.label}
              </button>
            )}
            <button
              onClick={() => dismissToast(t.id)}
              aria-label="Dismiss"
              className="-m-1 grid size-6 place-items-center rounded-sm text-muted hover:text-ink focus-visible:outline-2 focus-visible:outline-focus"
            >
              <X className="size-4" />
            </button>
          </li>
        );
      })}
    </ol>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { CircleAlert, CircleCheck, Info, TriangleAlert, X } from "lucide-react";
import { cn } from "@/lib/cn";

const alertVariants = cva("relative flex gap-3 rounded-card border p-3.5 text-sm", {
  variants: {
    variant: {
      info: "border-rule bg-paper-2 text-ink [&>svg]:text-accent",
      success: "border-transparent bg-success-wash text-success-wash-ink",
      warning: "border-transparent bg-warning-wash text-warning-wash-ink",
      danger: "border-transparent bg-danger-wash text-danger-wash-ink",
    },
  },
  defaultVariants: { variant: "info" },
});

const icons = { info: Info, success: CircleCheck, warning: TriangleAlert, danger: CircleAlert };

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">, VariantProps<typeof alertVariants> {
  title?: React.ReactNode;
  action?: React.ReactNode;
  onDismiss?: () => void;
}

export function Alert({ className, variant = "info", title, action, onDismiss, children, ...props }: AlertProps) {
  const Icon = icons[variant ?? "info"];
  return (
    <div role="alert" className={cn(alertVariants({ variant }), className)} {...props}>
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div className="grid flex-1 gap-1">
        {title && <p className="font-medium">{title}</p>}
        {children && <div className="opacity-90">{children}</div>}
        {action && <div className="mt-1.5 flex gap-2">{action}</div>}
      </div>
      {onDismiss && (
        <button
          onClick={onDismiss}
          aria-label="Dismiss"
          className="-m-1 grid size-6 place-items-center rounded-sm opacity-70 hover:opacity-100 focus-visible:outline-2 focus-visible:outline-focus"
        >
          <X className="size-4" />
        </button>
      )}
    </div>
  );
}

import * as React from "react";
import { Progress as ProgressPrimitive } from "radix-ui";
import { cn } from "@/lib/cn";

export function Progress({
  value = 0,
  className,
  tone = "accent",
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root> & { tone?: "accent" | "success" | "danger" }) {
  const fill = { accent: "bg-accent [background-image:var(--control-on-image)]", success: "bg-success", danger: "bg-danger" }[tone];
  const v = Math.min(100, Math.max(0, value ?? 0));
  return (
    <ProgressPrimitive.Root
      value={v}
      className={cn("relative h-2 w-full overflow-hidden rounded-full bg-[color:var(--track-off)] shadow-[inset_0_1px_1px_oklch(0%_0_0/0.06)]", className)}
      {...props}
    >
      <ProgressPrimitive.Indicator
        className={cn("h-full w-full rounded-full transition-transform duration-[var(--dur-short)] ease-[var(--ease-out)]", fill)}
        style={{ transform: `translateX(-${100 - v}%)` }}
      />
    </ProgressPrimitive.Root>
  );
}

/** A meter of discrete cells, useful for quotas and usage. */
export function Meter({ value, cells = 24, className, label }: { value: number; cells?: number; className?: string; label?: string }) {
  const on = Math.round((value / 100) * cells);
