import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/cn";

function range(page: number, count: number, siblings: number): (number | "gap")[] {
  const total = siblings * 2 + 5;
  if (count <= total) return Array.from({ length: count }, (_, i) => i + 1);
  const left = Math.max(page - siblings, 2);
  const right = Math.min(page + siblings, count - 1);
  const out: (number | "gap")[] = [1];
  if (left > 2) out.push("gap");
  for (let i = left; i <= right; i++) out.push(i);
  if (right < count - 1) out.push("gap");
  out.push(count);
  return out;
}

export interface PaginationProps {
  page: number;
  pageCount: number;
  onPageChange: (page: number) => void;
  /** Pages shown either side of the current one. */
  siblings?: number;
  /** Show the "Previous" and "Next" words. Turn off in narrow places; the arrows stay, with labels for screen readers. */
  labels?: boolean;
  className?: string;
}

const cell =
  "inline-flex h-8 min-w-8 items-center justify-center gap-1 rounded-input px-2 text-sm font-medium transition-[background-color,color] duration-[var(--dur-micro)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus disabled:pointer-events-none disabled:opacity-40";

export function Pagination({ page, pageCount, onPageChange, siblings = 1, labels = true, className }: PaginationProps) {
  return (
    <nav aria-label="Pagination" className={cn("flex max-w-full items-center gap-1", className)}>
      <button className={cn(cell, "text-ink-2 hover:bg-paper-3")} disabled={page <= 1} onClick={() => onPageChange(page - 1)} aria-label={labels ? undefined : "Previous page"}>
        <ChevronLeft className="size-4" /> {labels && <span className="hidden sm:inline">Previous</span>}
      </button>
      {range(page, pageCount, siblings).map((p, i) =>
        p === "gap" ? (
          <span key={`g${i}`} className="px-1 text-muted">…</span>
        ) : (
          <button
            key={p}
            aria-current={p === page ? "page" : undefined}
            onClick={() => onPageChange(p)}
            className={cn(
              cell,
              "tabular-nums",
              p === page ? "vx-glass border border-[color:var(--key-border)] bg-key-face text-ink shadow-key" : "text-ink-2 hover:bg-paper-3",
            )}
          >
            {p}
          </button>
        ),
      )}
      <button className={cn(cell, "text-ink-2 hover:bg-paper-3")} disabled={page >= pageCount} onClick={() => onPageChange(page + 1)} aria-label={labels ? undefined : "Next page"}>
        {labels && <span className="hidden sm:inline">Next</span>} <ChevronRight className="size-4" />
      </button>
    </nav>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";

/**
 * Buttons fused into one row: inner corners square, borders shared.
 * Put Button elements inside; pass aria-label to describe the group.
 */
export function ButtonGroup({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      role="group"
      className={cn(
        "inline-flex items-stretch [&>*]:rounded-none [&>*:first-child]:rounded-l-input [&>*:last-child]:rounded-r-input [&>*:not(:first-child)]:-ml-px [&>*]:shadow-none [&>*:focus-visible]:z-10 [&>*:hover]:z-10",
        className,
      )}
      {...props}
    />
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";

export interface BarDatum {
  label: string;
  value: number;
}

export interface BarChartProps {
  data: BarDatum[];
  height?: number;
  /** Format values in the tooltip and axis. */
  format?: (n: number) => string;
  /** Number of horizontal guide lines. */
  ticks?: number;
  /** Index drawn in the full accent; the rest use a lighter tint. */
  highlight?: number;
  /** Show the value axis on the left. Turn off in tight cards. */
  axis?: boolean;
  className?: string;
  "aria-label"?: string;
}

/** Each bar blends up from its partner hue into the accent; solid in Flat and Brutal. */
const BAR_FILL = `linear-gradient(to top, ${blendFrom("var(--accent)")}, var(--accent))`;

/** Rounded bars on a track. Bars grow with clip-path, hover or focus a bar for its value. */
export function BarChart({ data, height = 200, format = (n) => n.toLocaleString(), ticks = 4, highlight, axis = true, className, ...rest }: BarChartProps) {
  const max = Math.max(...data.map((d) => d.value), 1);
  const top = niceMax(max);
  const [hover, setHover] = React.useState<number | null>(null);
  const [ready, setReady] = React.useState(false);
  React.useEffect(() => {
    const r = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(r);
  }, []);
  return (
    <div className={cn("grid gap-x-3 gap-y-2", axis ? "grid-cols-[auto_minmax(0,1fr)]" : "grid-cols-[0_minmax(0,1fr)] gap-x-0", className)} role="img" aria-label={rest["aria-label"] ?? "Bar chart"}>
      <div className={cn("relative text-right text-[11px] tabular-nums text-muted", !axis && "invisible")} style={{ height }}>
        {Array.from({ length: ticks + 1 }, (_, i) => (
          <span key={i} className="absolute right-0 -translate-y-1/2" style={{ top: `${(i / ticks) * 100}%` }}>
            {format(Math.round(top - (top / ticks) * i))}
          </span>
        ))}
      </div>
      <div className="relative" style={{ height }}>
        {Array.from({ length: ticks + 1 }, (_, i) => (
          <span key={i} aria-hidden className="absolute inset-x-0 border-t border-dashed border-rule" style={{ top: `${(i / ticks) * 100}%` }} />
        ))}
        <div className="absolute inset-0 flex items-stretch gap-[6%] px-[2%]" onMouseLeave={() => setHover(null)}>
          {data.map((d, i) => {
            const pct = (d.value / top) * 100;
            const on = hover === i || (hover === null && highlight === i);
            return (
              <button
                key={d.label}
                type="button"
                aria-label={`${d.label}: ${format(d.value)}`}
                onMouseEnter={() => setHover(i)}
                onFocus={() => setHover(i)}
                onBlur={() => setHover(null)}
                className="group relative flex-1 rounded-[6px] bg-paper-2 outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus"
              >
                <span
                  className={cn(
                    "absolute inset-0 rounded-[6px] transition-[clip-path,opacity] duration-700 ease-[var(--ease-out)]",
                    on ? "opacity-100" : hover !== null ? "opacity-35" : "opacity-60",
                  )}
                  style={{ backgroundImage: BAR_FILL, backgroundSize: `100% ${Math.max(pct, 1)}%`, backgroundPosition: "bottom", backgroundRepeat: "no-repeat", clipPath: `inset(${ready ? 100 - pct : 100}% 0 0 0 round 6px)`, transitionDelay: ready ? "0ms" : `${i * 40}ms` }}
                />
                {hover === i && (
                  <span className="vx-fade-up pointer-events-none absolute left-1/2 z-10 -translate-x-1/2 whitespace-nowrap rounded-input bg-graphite px-2 py-1 text-xs font-medium text-graphite-ink shadow-pop" style={{ bottom: `calc(${pct}% + 8px)` }}>
                    {d.label} · {format(d.value)}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </div>
      <span />
      <div className="flex gap-[6%] px-[2%] text-center text-[11px] text-muted">
        {data.map((d) => <span key={d.label} className="flex-1 truncate">{d.label}</span>)}
      </div>
    </div>
  );
}

/** Round a maximum up to a tidy axis value. */
export function niceMax(n: number) {
  const p = Math.pow(10, Math.floor(Math.log10(n)));
  const m = n / p;
  return (m <= 1 ? 1 : m <= 2 ? 2 : m <= 2.5 ? 2.5 : m <= 5 ? 5 : 10) * p;
}

/* ───────── Shared chart helpers, used by the other charts ───────── */

/** A point on a chart, in SVG units. */
export type Point = readonly [number, number];

function sign(n: number) {
  return n < 0 ? -1 : 1;
}

/**
 * A smooth SVG path through the points, using monotone cubic interpolation (the "monotone" curve most chart
 * libraries default to). It bends gently through every point without overshooting, so a line never dips
 * below a real minimum or rises above a real maximum between two values.
 */
export function smoothPath(pts: readonly Point[]): string {
  const n = pts.length;
  if (!n) return "";
  if (n < 3) return pts.map(([x, y], i) => `${i ? "L" : "M"} ${x} ${y}`).join(" ");

  // Slope of each segment, then a tangent at each point that keeps the curve monotone between points.
  const h = pts.slice(1).map(([x], i) => x - pts[i][0]);
  const s = pts.slice(1).map(([, y], i) => (y - pts[i][1]) / (h[i] || 1));
  const t = pts.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const [s0, s1, h0, h1] = [s[i - 1], s[i], h[i - 1], h[i]];
    const p = (s0 * h1 + s1 * h0) / (h0 + h1);
    return (sign(s0) + sign(s1)) * Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0;
  });
  // The ends lean into their neighbour instead of starting flat.
  t[0] = (3 * s[0] - t[1]) / 2;
  t[n - 1] = (3 * s[n - 2] - t[n - 2]) / 2;

  let d = `M ${pts[0][0]} ${pts[0][1]}`;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = pts[i];
    const [x1, y1] = pts[i + 1];
    const k = h[i] / 3;
    d += ` C ${x0 + k} ${y0 + t[i] * k}, ${x1 - k} ${y1 - t[i + 1] * k}, ${x1} ${y1}`;
  }
  return d;
}

/**
 * The partner colour a series blends from: the same colour turned around the hue wheel and lifted, by amounts
 * each style sets (--chart-shift, --chart-lift). In Flat and Brutal both are 0, so charts stay solid.
 */
export function blendFrom(color: string) {
  return `oklch(from ${color} calc(l + var(--chart-lift, 0)) c calc(h + var(--chart-shift, 0)))`;
}

import * as React from "react";
import { Check, Eye, EyeOff, Lock, X } from "lucide-react";
import { cn } from "@/lib/cn";
import { Input, type InputProps } from "./input";

const rules = [
  { label: "At least 8 characters", test: (v: string) => v.length >= 8 },
  { label: "An uppercase letter", test: (v: string) => /[A-Z]/.test(v) },
  { label: "A number", test: (v: string) => /\d/.test(v) },
  { label: "A symbol", test: (v: string) => /[^A-Za-z0-9]/.test(v) },
];
const levels = ["Too weak", "Weak", "Fair", "Good", "Strong"];
const tone = ["bg-paper-3", "bg-danger", "bg-warning", "bg-accent", "bg-success"];

export interface PasswordInputProps extends Omit<InputProps, "type" | "trailing"> {
  /** Show a four-step strength meter and the rules under the field. */
  showStrength?: boolean;
}

/** A password field with a show and hide key, and an optional strength meter. */
export const PasswordInput = React.forwardRef<HTMLInputElement, PasswordInputProps>(
  ({ showStrength, value, defaultValue, onChange, className, ...props }, ref) => {
    const [shown, setShown] = React.useState(false);
    const [inner, setInner] = React.useState(String(defaultValue ?? ""));
    const v = value === undefined ? inner : String(value);
    const score = rules.filter((r) => r.test(v)).length;
    return (
      <div className={cn("grid gap-2", className)}>
        <Input
          ref={ref}
          type={shown ? "text" : "password"}
          value={v}
          onChange={(e) => {
            setInner(e.target.value);
            onChange?.(e);
          }}
          leading={<Lock />}
          trailing={
            <button
              type="button"
              onClick={() => setShown(!shown)}
              aria-label={shown ? "Hide password" : "Show password"}
              aria-pressed={shown}
              className="grid size-7 place-items-center rounded-sm text-muted hover:text-ink focus-visible:outline-2 focus-visible:outline-focus"
            >
              {shown ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
            </button>
          }
          {...props}
        />
        {showStrength && (
          <div className="grid gap-2" aria-live="polite">
            <div className="flex items-center gap-2">
              <div className="grid flex-1 grid-cols-4 gap-1">
                {[1, 2, 3, 4].map((i) => (
                  <span key={i} className={cn("h-1.5 rounded-full transition-[background-color] duration-[var(--dur-short)]", score >= i ? tone[score] : "bg-paper-3")} />
                ))}
              </div>
              <span className="w-16 text-right text-xs text-muted">{v ? levels[score] : ""}</span>
            </div>
            <ul className="grid grid-cols-2 gap-x-3 gap-y-1 text-xs">
              {rules.map((r) => {
                const ok = r.test(v);
                return (
                  <li key={r.label} className={cn("flex items-center gap-1.5", ok ? "text-success-wash-ink" : "text-muted")}>
                    {ok ? <Check className="size-3.5" /> : <X className="size-3.5" />} {r.label}
                  </li>
                );
              })}
            </ul>
          </div>
        )}
      </div>
    );
  },
);
PasswordInput.displayName = "PasswordInput";

import * as React from "react";
import { Check, Copy } from "lucide-react";
import { Button, type ButtonProps } from "./button";

export interface CopyButtonProps extends Omit<ButtonProps, "onClick"> {
  /** The text written to the clipboard. */
  value: string;
  /** Text shown beside the icon. Omit for an icon-only button. */
  label?: string;
  onCopied?: () => void;
}

/** Copies a value and confirms with a check for a moment. */
export function CopyButton({ value, label, onCopied, variant = "secondary", size, ...props }: CopyButtonProps) {
  const [done, setDone] = React.useState(false);
  return (
    <Button
      variant={variant}
      size={size ?? (label ? "sm" : "icon-sm")}
      aria-label={label ? undefined : done ? "Copied" : "Copy"}
      onClick={() =>
        navigator.clipboard?.writeText(value).then(() => {
          setDone(true);
          onCopied?.();
          window.setTimeout(() => setDone(false), 1500);
        })
      }
      {...props}
    >
      {done ? <Check className="text-success" /> : <Copy />}
      {label && (done ? "Copied" : label)}
    </Button>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";
import { blendFrom, smoothPath } from "./bar-chart";

export interface SparklineProps {
  values: number[];
  width?: number;
  height?: number;
  /** Fill under the line. */
  area?: boolean;
  /** Any CSS colour; defaults to the accent. */
  color?: string;
  /** Mark the last point. */
  showLast?: boolean;
  className?: string;
  "aria-label"?: string;
}

/** A small trend line for tables, stats and cards. */
export function Sparkline({ values, width = 120, height = 36, area, color = "var(--accent)", showLast, className, ...rest }: SparklineProps) {
  const id = React.useId().replace(/:/g, "");
  const min = Math.min(...values);
  const max = Math.max(...values);
  const pts = values.map((v, i) => [(i / (values.length - 1)) * width, height - 3 - ((v - min) / (max - min || 1)) * (height - 6)] as const);
  const line = smoothPath(pts);
  const last = pts[pts.length - 1];
  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label={rest["aria-label"] ?? `Trend from ${values[0]} to ${values[values.length - 1]}`}
    >
      <defs>
        <linearGradient id={`${id}-s`} x1="0" x2="1" y1="0" y2="0">
          <stop offset="0%" style={{ stopColor: blendFrom(color) }} />
          <stop offset="100%" style={{ stopColor: color }} />
        </linearGradient>
        {area && (
          <linearGradient id={id} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" style={{ stopColor: color, stopOpacity: "var(--chart-area-a)" }} />
            <stop offset="100%" style={{ stopColor: color, stopOpacity: 0 }} />
          </linearGradient>
        )}
      </defs>
      {area && <path d={`${line} L ${width} ${height} L 0 ${height} Z`} fill={`url(#${id})`} />}
      <path d={line} fill="none" stroke={`url(#${id}-s)`} strokeWidth="1.75" strokeLinejoin="round" strokeLinecap="round" pathLength={1} className="vx-draw" />
      {showLast && <circle cx={last[0]} cy={last[1]} r="2.75" fill={color} stroke="var(--paper)" strokeWidth="1.5" />}
    </svg>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";
import { blendFrom, niceMax, smoothPath, type Point } from "./bar-chart";

export interface LineSeries {
  name: string;
  values: number[];
  color?: string;
  /** Draw as a dashed line, for targets or last period. */
  dashed?: boolean;
}

export interface LineChartProps {
  labels: string[];
  series: LineSeries[];
  height?: number;
  /** Smooth curves instead of straight segments. */
  curved?: boolean;
  /** Show the legend above the plot. */
  legend?: boolean;
  format?: (n: number) => string;
  className?: string;
  "aria-label"?: string;
}

const palette = ["var(--accent)", "var(--chart-2)", "var(--chart-3)", "var(--chart-4)", "var(--chart-5)"];

function toPath(pts: Point[], curved: boolean) {
  return curved ? smoothPath(pts) : pts.map(([x, y], i) => `${i ? "L" : "M"} ${x} ${y}`).join(" ");
}

/** Lines with a y axis, a legend and dashed comparison series. Hover or arrow through points. */
export function LineChart({ labels, series, height = 240, curved = true, legend = true, format = (n) => n.toLocaleString(), className, ...rest }: LineChartProps) {
  const W = 600;
  const H = height;
  const top = niceMax(Math.max(...series.flatMap((s) => s.values), 1));
  const [hover, setHover] = React.useState<number | null>(null);
  const ref = React.useRef<SVGSVGElement>(null);
  const id = React.useId().replace(/:/g, "");
  const step = W / Math.max(1, labels.length - 1);
  const color = (s: LineSeries, i: number) => s.color ?? palette[i % palette.length];
  const y = (v: number) => H - (v / top) * H;
  const pick = (clientX: number) => {
    const r = ref.current!.getBoundingClientRect();
    setHover(Math.max(0, Math.min(labels.length - 1, Math.round((((clientX - r.left) / r.width) * W) / step))));
  };
  const ticks = [1, 0.75, 0.5, 0.25, 0];
  return (
    <div className={cn("grid gap-3", className)}>
      {legend && (
        <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-ink-2">
          {series.map((s, i) => (
            <li key={s.name} className="flex items-center gap-1.5">
              <span aria-hidden className={cn("h-0.5 w-3 rounded-full", s.dashed && "bg-transparent border-t-2 border-dashed")} style={s.dashed ? { borderColor: color(s, i) } : { background: color(s, i) }} />
              {s.name}
            </li>
          ))}
        </ul>
      )}
      <div className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3">
        <div className="flex flex-col justify-between text-right text-[11px] tabular-nums text-muted" style={{ height: H }} aria-hidden>
          {ticks.map((t) => <span key={t} className="-translate-y-1/2 first:translate-y-0 last:translate-y-0">{format(Math.round(top * t))}</span>)}
        </div>
        <div className="relative">
          <svg
            ref={ref}
            viewBox={`0 0 ${W} ${H}`}
            preserveAspectRatio="none"
            className="block w-full overflow-visible outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-focus"
            style={{ height: H }}
            tabIndex={0}
            role="img"
            aria-label={rest["aria-label"] ?? "Line chart"}
            onMouseMove={(e) => pick(e.clientX)}
            onMouseLeave={() => setHover(null)}
            onBlur={() => setHover(null)}
            onKeyDown={(e) => {
              if (e.key === "ArrowRight") setHover((h) => Math.min(labels.length - 1, (h ?? -1) + 1));
              if (e.key === "ArrowLeft") setHover((h) => Math.max(0, (h ?? labels.length) - 1));
            }}
          >
            {ticks.map((t) => (
              <line key={t} x1="0" x2={W} y1={(1 - t) * H} y2={(1 - t) * H} stroke="var(--rule)" strokeDasharray={t === 0 ? undefined : "4 4"} vectorEffect="non-scaling-stroke" />
            ))}
            {hover !== null && <line x1={hover * step} x2={hover * step} y1="0" y2={H} stroke="var(--rule-2)" vectorEffect="non-scaling-stroke" />}
            <defs>
              {series.map((s, i) => (
                <React.Fragment key={s.name}>
                  <linearGradient id={`${id}-s${i}`} x1="0" x2="1" y1="0" y2="0">
                    <stop offset="0%" style={{ stopColor: blendFrom(color(s, i)) }} />
                    <stop offset="100%" style={{ stopColor: color(s, i) }} />
                  </linearGradient>
                  <linearGradient id={`${id}-f${i}`} x1="0" x2="0" y1="0" y2="1">
                    <stop offset="0%" style={{ stopColor: color(s, i), stopOpacity: "var(--chart-area-a)" }} />
                    <stop offset="100%" style={{ stopColor: color(s, i), stopOpacity: 0 }} />
                  </linearGradient>
                </React.Fragment>
              ))}
            </defs>
            {series.map((s, i) =>
              s.dashed || i > 0 ? null : (
                <path key={s.name} d={`${toPath(s.values.map((v, j) => [j * step, y(v)] as const), curved)} L ${(s.values.length - 1) * step} ${H} L 0 ${H} Z`} fill={`url(#${id}-f${i})`} className="vx-fade-up" />
              ),
            )}
            <g className="vx-wipe">
            {series.map((s, i) => (
              <path
                key={s.name}
                d={toPath(s.values.map((v, j) => [j * step, y(v)] as const), curved)}
                fill="none"
                stroke={s.dashed ? color(s, i) : `url(#${id}-s${i})`}
                strokeWidth="2.25"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={s.dashed ? "6 6" : undefined}
                vectorEffect="non-scaling-stroke"
              />
            ))}
            </g>
          </svg>
          {hover !== null && (
            <>
              {series.map((s, i) => (
                <span
                  key={s.name}
                  aria-hidden
                  className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-paper"
                  style={{ left: `${(hover / Math.max(1, labels.length - 1)) * 100}%`, top: y(s.values[hover]), background: color(s, i) }}
                />
              ))}
              <div
                className="vx-fade-up pointer-events-none absolute top-0 z-10 grid min-w-32 gap-1 rounded-card border border-pop-border bg-pop p-2.5 text-xs shadow-pop"
                style={{ left: `${(hover / Math.max(1, labels.length - 1)) * 100}%`, transform: `translateX(${hover > labels.length / 2 ? "calc(-100% - 12px)" : "12px"})` }}
              >
                <span className="font-medium text-ink">{labels[hover]}</span>
                {series.map((s, i) => (
                  <span key={s.name} className="flex items-center gap-2 text-ink-2">
                    <span className="size-2 rounded-full" style={{ background: color(s, i) }} />
                    {s.name}
                    <span className="ml-auto font-medium tabular-nums text-ink">{format(s.values[hover])}</span>
                  </span>
                ))}
              </div>
            </>
          )}
          <div className="mt-2 flex justify-between text-[11px] text-muted" aria-hidden>
            {labels.map((l, i) => <span key={i}>{l}</span>)}
          </div>
        </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";

export interface BarListItem {
  name: string;
  value: number;
  /** An icon or favicon shown before the name. */
  icon?: React.ReactNode;
  href?: string;
}

export interface BarListProps {
  items: BarListItem[];
  /** Sort from largest to smallest. */
  sorted?: boolean;
  /** Show only the first n, with a toggle for the rest. */
  limit?: number;
  format?: (n: number) => string;
  /** Header labels for the name and value columns. */
  columns?: [string, string];
  className?: string;
}

/** Ranked rows with a bar behind each name, for top pages, sources or countries. */
export function BarList({ items, sorted = true, limit, format = (n) => n.toLocaleString(), columns, className }: BarListProps) {
  const [all, setAll] = React.useState(false);
  const rows = sorted ? [...items].sort((a, b) => b.value - a.value) : items;
  const shown = limit && !all ? rows.slice(0, limit) : rows;
  const max = Math.max(...items.map((i) => i.value), 1);
  return (
    <div className={cn("grid gap-1.5", className)}>
      {columns && (
        <div className="flex justify-between px-2 pb-1 text-xs text-muted">
          <span>{columns[0]}</span>
          <span>{columns[1]}</span>
        </div>
      )}
      <ul className="grid gap-1.5">
        {shown.map((item, i) => {
          const body = (
            <>
              <span
                aria-hidden
                className="vx-grow-x absolute inset-y-0 left-0 rounded-sm bg-accent/14 group-hover:bg-accent/22"
                style={{ width: `${(item.value / max) * 100}%`, animationDelay: `${i * 40}ms` }}
              />
              <span className="relative flex min-w-0 items-center gap-2 [&_svg]:size-4 [&_svg]:text-muted">
                {item.icon}
                <span className="truncate">{item.name}</span>
              </span>
              <span className="relative tabular-nums text-ink">{format(item.value)}</span>
            </>
          );
          const row = "group relative flex h-8 items-center justify-between gap-3 px-2 text-sm text-ink-2";
          return (
            <li key={item.name}>
              {item.href ? (
                <a href={item.href} className={cn(row, "rounded-sm hover:text-ink focus-visible:outline-2 focus-visible:outline-focus")}>{body}</a>
              ) : (
                <div className={row}>{body}</div>
              )}
            </li>
          );
        })}
      </ul>
      {limit && rows.length > limit && (
        <button
          type="button"
          onClick={() => setAll((v) => !v)}
          className="justify-self-start rounded-sm px-2 py-1 text-xs font-medium text-accent hover:underline focus-visible:outline-2 focus-visible:outline-focus"
        >
          {all ? "Show less" : `Show all ${rows.length}`}
        </button>
      )}
    </div>
  );
}

import { cn } from "@/lib/cn";

export interface Stage {
  label: string;
  value: number;
  color?: string;
}

export interface StageBarsProps {
  /** One row per item, each split into the same stages. */
  rows: { label: string; stages: Stage[] }[];
  format?: (n: number) => string;
  /** Show the stage legend. */
  legend?: boolean;
  className?: string;
}

const palette = ["var(--accent)", "var(--chart-3)", "var(--chart-2)", "var(--chart-5)", "var(--chart-4)"];

/** Horizontal bars split into stages, such as sleep phases or a deal pipeline per rep. */
export function StageBars({ rows, format = (n) => n.toLocaleString(), legend = true, className }: StageBarsProps) {
  const max = Math.max(...rows.map((r) => r.stages.reduce((a, s) => a + s.value, 0)), 1);
  const stageNames = rows[0]?.stages ?? [];
  return (
    <div className={cn("grid gap-3", className)}>
      {legend && (
        <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-ink-2">
          {stageNames.map((s, i) => <li key={s.label} className="flex items-center gap-1.5"><span aria-hidden className="size-2.5 rounded-[3px]" style={{ background: s.color ?? palette[i % 5] }} />{s.label}</li>)}
        </ul>
      )}
      <ul className="grid gap-2.5">
        {rows.map((r, ri) => {
          const total = r.stages.reduce((a, s) => a + s.value, 0);
          return (
            <li key={r.label} className="grid grid-cols-[88px_minmax(0,1fr)_auto] items-center gap-3 text-sm">
              <span className="truncate text-ink-2">{r.label}</span>
              <span
                className="vx-grow-x flex h-3 gap-0.5 overflow-hidden rounded-full"
                style={{ width: `${(total / max) * 100}%`, animationDelay: `${ri * 60}ms` }}
                role="img"
                aria-label={`${r.label}: ${r.stages.map((s) => `${s.label} ${format(s.value)}`).join(", ")}`}
              >
                {r.stages.map((s, i) => <span key={s.label} title={`${s.label}: ${format(s.value)}`} className="h-full first:rounded-l-full last:rounded-r-full" style={{ flexGrow: s.value, background: s.color ?? palette[i % 5] }} />)}
              </span>
              <span className="text-right tabular-nums text-ink">{format(total)}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import * as React from "react";
import { TrendingDown, TrendingUp } from "lucide-react";
import { cn } from "@/lib/cn";

export interface ChartCardProps {
  title: string;
  /** The headline number. */
  value?: React.ReactNode;
  /** Percent change, shown as a pill beside the value. */
  delta?: number;
  invert?: boolean;
  /** Text after the value, such as "this week". */
  caption?: React.ReactNode;
  /** Controls in the header, such as a period switcher. */
  action?: React.ReactNode;
  /** A white strip under the chart for a takeaway or a link. */
  footer?: React.ReactNode;
  children: React.ReactNode;
  /** Drop the card and the inner panel, for a chart that already sits on a surface of its own. */
  flat?: boolean;
  className?: string;
}

/** The shell every chart card shares: a grey card, the title and number, the chart on a white panel, and an optional footer. */
export function ChartCard({ title, value, delta, invert, caption, action, footer, children, flat, className }: ChartCardProps) {
  const good = delta === undefined ? undefined : invert ? delta < 0 : delta >= 0;
  const Trend = delta !== undefined && delta < 0 ? TrendingDown : TrendingUp;
  return (
    <section aria-label={title} className={cn("flex min-w-0 flex-col text-ink", flat ? "gap-4" : "vx-glass gap-2 rounded-panel border border-card-border bg-card p-2 shadow-card", className)}>
      <header className={cn("flex items-start justify-between gap-3", !flat && "px-2.5 pt-2")}>
        <div className="grid min-w-0 gap-1">
          <h3 className="text-sm font-medium text-muted">{title}</h3>
          {value !== undefined && (
            <p className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
              <span className="text-2xl font-semibold tracking-[-0.02em] tabular-nums">{value}</span>
              {delta !== undefined && (
                <span className={cn("flex items-center gap-0.5 self-center rounded-full py-0.5 pl-1 pr-1.5 text-xs font-semibold", good ? "bg-success-wash text-success-wash-ink" : "bg-danger-wash text-danger-wash-ink")}>
                  <Trend className="size-3" /> {Math.abs(delta)}%
                </span>
              )}
              {caption && <span className="text-sm text-muted">{caption}</span>}
            </p>
          )}
        </div>
        {action && <div className="shrink-0">{action}</div>}
      </header>
      <div className={cn(!flat && "rounded-input bg-paper p-3 shadow-[0_1px_1px_oklch(0%_0_0/0.05)]")}>{children}</div>
      {footer && <div className={cn("text-sm text-muted", flat ? "border-t border-rule pt-3" : "px-2.5 pb-1")}>{footer}</div>}
    </section>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";
import { ChartCard } from "./chart-card";

export interface StepsCardProps {
  days?: { label: string; value: number }[];
  goal?: number;
  className?: string;
}

const week = [
  { label: "Mon", value: 8420 }, { label: "Tue", value: 11240 }, { label: "Wed", value: 6310 }, { label: "Thu", value: 10380 },
  { label: "Fri", value: 12950 }, { label: "Sat", value: 4120 }, { label: "Sun", value: 9060 },
];

/** Daily steps against a dashed goal line. Days over the goal are filled; hover a day for its count. */
export function StepsCard({ days = week, goal = 10000, className }: StepsCardProps) {
  const [hover, setHover] = React.useState<number | null>(null);
  const max = Math.max(goal * 1.25, ...days.map((d) => d.value));
  const total = days.reduce((a, d) => a + d.value, 0);
  const hit = days.filter((d) => d.value >= goal).length;
  const H = 150;
  return (
    <ChartCard className={className} title="Steps" value={Math.round(total / days.length).toLocaleString()} caption="a day on average" footer={`Goal met on ${hit} of ${days.length} days.`}>
      <div className="relative" style={{ height: H }}>
        <span aria-hidden className="absolute inset-x-0 border-t border-dashed border-muted/60" style={{ bottom: (goal / max) * H }}>
          <span className="absolute -top-2.5 right-0 bg-paper pl-1 text-[11px] text-muted">{goal.toLocaleString()}</span>
        </span>
        <ul className="relative flex h-full items-end gap-2" aria-label="Steps by day">
          {days.map((d, i) => {
            const over = d.value >= goal;
            return (
              <li
                key={d.label}
                className="relative flex h-full flex-1 items-end"
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(null)}
                tabIndex={0}
                onFocus={() => setHover(i)}
                onBlur={() => setHover(null)}
                aria-label={`${d.label}: ${d.value.toLocaleString()} steps`}
              >
                <span
                  className={cn("vx-rise w-full rounded-[6px] transition-opacity duration-[var(--dur-micro)]", over ? "bg-accent [background-image:var(--control-on-image)]" : "bg-accent/25", hover !== null && hover !== i && "opacity-50")}
                  style={{ height: `${(d.value / max) * 100}%`, transformOrigin: "bottom", animationDelay: `${i * 40}ms` }}
                />
                {hover === i && (
                  <span className="pointer-events-none absolute bottom-full left-1/2 z-10 mb-1 -translate-x-1/2 whitespace-nowrap rounded-input border border-pop-border bg-pop px-2 py-1 text-xs font-medium tabular-nums shadow-pop">{d.value.toLocaleString()}</span>
                )}
              </li>
            );
          })}
        </ul>
      </div>
      <div aria-hidden className="mt-2 flex gap-2 text-center text-[11px] text-muted">{days.map((d) => <span key={d.label} className="flex-1">{d.label}</span>)}</div>
    </ChartCard>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";
import { ChartCard } from "./chart-card";

export interface ActiveDaysCardProps {
  /** Seven values, Monday first. */
  values?: number[];
  /** Unit for the tooltip, such as "sessions". */
  unit?: string;
  className?: string;
}

const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const long = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

/** Which weekday is busiest: seven rounded columns with the peak lit and named. */
export function ActiveDaysCard({ values = [62, 78, 96, 84, 70, 34, 28], unit = "sessions", className }: ActiveDaysCardProps) {
  const [hover, setHover] = React.useState<number | null>(null);
  const max = Math.max(...values, 1);
  const peak = values.indexOf(max);
  const shown = hover ?? peak;
  return (
    <ChartCard className={className} title="Most active days" value={long[peak]} caption={`${max} ${unit} on average`}>
      <div className="flex h-36 items-end gap-2">
        {values.map((v, i) => (
          <button
            key={days[i]}
            type="button"
            aria-label={`${long[i]}: ${v} ${unit}`}
            onMouseEnter={() => setHover(i)}
            onMouseLeave={() => setHover(null)}
            onFocus={() => setHover(i)}
            onBlur={() => setHover(null)}
            className="group relative flex h-full flex-1 items-end rounded-[8px] bg-paper-2 focus-visible:outline-2 focus-visible:outline-focus"
          >
            <span
              className={cn("vx-rise w-full rounded-[8px] transition-colors duration-[var(--dur-micro)]", i === shown ? "bg-accent [background-image:var(--control-on-image)]" : "bg-accent/20 group-hover:bg-accent/35")}
              style={{ height: `${(v / max) * 100}%`, transformOrigin: "bottom", animationDelay: `${i * 40}ms` }}
            />
          </button>
        ))}
      </div>
      <div aria-hidden className="mt-2 flex gap-2 text-center text-[11px] text-muted">
        {days.map((d, i) => <span key={d} className={cn("flex-1", i === shown && "font-medium text-ink")}>{d}</span>)}
      </div>
      <p className="mt-2 text-center text-xs text-muted" aria-live="polite">{long[shown]}: <b className="font-medium tabular-nums text-ink">{values[shown]}</b> {unit}</p>
    </ChartCard>
  );
}
